/* ================================
   Appointment / Chamber Section
   ================================ */

.appointment-section {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px 0 40px;
    box-sizing: border-box;
}


/* ================================
   Header
   ================================ */

.appointment-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 40px;

    padding-bottom: 38px;
    margin-bottom: 24px;

    border-bottom: 1px solid #e1e5ea;
}

.appointment-badge {
    display: inline-block;

    padding: 5px 13px;

    border: 1px solid #a9d2f5;
    border-radius: 20px;

    color: #1473b8;
    background: #f4faff;

    font-size: 14px;
    line-height: 1.4;
    font-weight: 500;
}

.appointment-header h2 {
    margin: 10px 0 0;

    color: #062f5b;

    font-size: 34px;
    line-height: 1.3;
    font-weight: 700;
}

.appointment-description {
    max-width: 330px;

    margin: 17px 0 0;

    color: #526274;

    font-size: 15px;
    line-height: 1.8;
    text-align: right;
}


/* ================================
   Card Grid
   ================================ */

.appointment-grid {
    display: grid;

    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 24px;

    align-items: stretch;
}


/* ================================
   Main Card
   ================================ */

.appointment-card {
    display: flex;
    flex-direction: column;

    min-width: 0;

    padding: 28px;

    border-radius: 24px;

    box-sizing: border-box;

    overflow: hidden;

    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease;
}

.appointment-card:hover {
    transform: translateY(-4px);

    box-shadow:
        0 14px 35px rgba(0, 0, 0, 0.08);
}


/* ================================
   Card Colors
   ================================ */

.appointment-card-pink {
    background: #f8d3d7;
}

.appointment-card-green {
    background: #d4efdf;
}

.appointment-card-blue {
    background: #d9e7f6;
}


/* ================================
   Logo
   ================================ */

.appointment-logo {
    height: 92px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin-bottom: 6px;
}

.appointment-logo img {
    display: block;

    max-width: 155px;
    max-height: 75px;

    width: auto;
    height: auto;

    object-fit: contain;
}


/* ================================
   Card Title
   ================================ */

.appointment-card h3 {
    margin: 0 0 24px;

    color: #06315d;

    font-size: 21px;
    line-height: 1.5;
    font-weight: 700;

    text-align: center;
}


/* ================================
   Information Box
   ================================ */

.appointment-info {
    padding: 20px;

    background: #f8fafc;

    border-radius: 18px;

    box-sizing: border-box;
}

.info-item {
    margin-bottom: 14px;
}

.info-item:last-child {
    margin-bottom: 0;
}

.info-label {
    display: block;

    margin-bottom: 4px;

    color: #758296;

    font-size: 13px;
    line-height: 1.5;
}

.info-item strong {
    display: block;

    color: #092f5c;

    font-size: 16px;
    line-height: 1.55;
    font-weight: 600;
}

.info-item .closed-day {
    color: #ff1744;
}


/* ================================
   Divider
   ================================ */

.info-divider {
    height: 1px;

    margin: 17px 0;

    background: #dce2e8;
}


/* ================================
   Contact
   ================================ */

.contact-item a {
    display: block;

    width: fit-content;

    margin-top: 3px;

    color: #063b76;

    font-size: 16px;
    line-height: 1.55;
    font-weight: 600;

    text-decoration: none;
}

.contact-item a:hover {
    text-decoration: underline;
}


/* ================================
   Location
   ================================ */

.appointment-location {
    display: flex;
    align-items: flex-start;

    gap: 9px;

    margin-top: 22px;
    margin-bottom: 20px;

    color: #18212b;

    font-size: 14px;
    line-height: 1.7;
}

.location-icon {
    flex: 0 0 auto;

    font-size: 20px;

    line-height: 1.3;
}


/* ================================
   Google Map Button
   ================================ */

.map-button {
    display: flex;
    align-items: center;
    justify-content: center;

    gap: 8px;

    width: 100%;

    margin-top: auto;
    padding: 12px 18px;

    border-radius: 11px;

    box-sizing: border-box;

    color: #ffffff;

    font-size: 14px;
    line-height: 1.5;
    font-weight: 600;

    text-decoration: none;

    transition:
        opacity 0.2s ease,
        transform 0.2s ease;
}

.map-button:hover {
    opacity: 0.88;

    transform: translateY(-1px);
}

.map-button span {
    font-size: 18px;

    line-height: 1;
}


/* Button Colors */

.map-button-pink {
    background: #ff646b;
}

.map-button-green {
    background: #008b3e;
}

.map-button-blue {
    background: #3989d6;
}


/* ================================
   Tablet
   ================================ */

@media (max-width: 991px) {

    .appointment-section {
        padding: 20px 16px 35px;
    }

    .appointment-header {
        gap: 25px;
    }

    .appointment-header h2 {
        font-size: 30px;
    }

    .appointment-description {
        max-width: 280px;

        font-size: 14px;
    }

    .appointment-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .appointment-card {
        padding: 24px;
    }

    .appointment-card h3 {
        font-size: 19px;
    }

    .info-item strong {
        font-size: 15px;
    }
}


/* ================================
   Mobile
   ================================ */

@media (max-width: 767px) {

    .appointment-section {
        padding: 15px 12px 30px;
    }

    .appointment-header {
        display: block;

        padding-bottom: 25px;
        margin-bottom: 20px;
    }

    .appointment-header h2 {
        font-size: 27px;
    }

    .appointment-description {
        max-width: none;

        margin-top: 14px;

        text-align: left;

        font-size: 14px;
    }

    .appointment-grid {
        grid-template-columns: 1fr;

        gap: 18px;
    }

    .appointment-card {
        padding: 22px;

        border-radius: 20px;
    }

    .appointment-logo {
        height: 85px;
    }

    .appointment-logo img {
        max-width: 145px;
        max-height: 68px;
    }

    .appointment-card h3 {
        margin-bottom: 20px;

        font-size: 20px;
    }

    .appointment-info {
        padding: 18px;
    }

    .appointment-location {
        font-size: 14px;
    }

    .map-button {
        padding: 13px 16px;
    }
}


/* ================================
   Small Mobile
   ================================ */

@media (max-width: 420px) {

    .appointment-header h2 {
        font-size: 24px;
    }

    .appointment-card {
        padding: 18px;
    }

    .appointment-card h3 {
        font-size: 18px;
    }

    .appointment-info {
        padding: 16px;
    }

    .info-item strong,
    .contact-item a {
        font-size: 14px;
    }

    .appointment-location {
        font-size: 13px;
    }
}

